<?php if (!in_array($_SESSION['role'],['admin','pimpinan','bendahara'],true)){http_response_code(403);exit('Akses ditolak.');} ?><h1>Keuangan</h1><p><a href="?page=laporan">Laporan periode, saldo, dan unduh CSV</a></p><?php if(in_array($_SESSION['role'],['admin','bendahara'],true)): ?><section class="card"><h2>Tambah Transaksi</h2><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><div class="formgrid"><label>Tanggal<input type="date" name="tanggal" value="<?=date('Y-m-d')?>" required></label><label>Jenis<select name="jenis" id="jenis" onchange="categories()"><option value="masuk">Pemasukan</option><option value="keluar">Pengeluaran</option></select></label><label>Kategori<select name="kategori" id="kategori"></select></label><label>Nominal (Rp)<input type="number" name="nominal" min=".01" step=".01" required></label><label>Uraian<input name="uraian" maxlength="255" required></label></div><button name="action" value="add_keuangan">Simpan Transaksi</button></form></section><?php endif; ?><section class="card"><h2>200 Transaksi Terbaru</h2><div class="tablewrap"><table><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Uraian</th><th>Nominal</th></tr></thead><tbody><?php foreach(db()->query('SELECT tanggal,jenis,kategori,uraian,nominal FROM transactions ORDER BY tanggal DESC,id DESC LIMIT 200') as $r): ?><tr><td><?=esc($r['tanggal'])?></td><td><?=esc($r['jenis'])?></td><td><?=esc($r['kategori'])?></td><td><?=esc($r['uraian'])?></td><td><?=rupiah($r['nominal'])?></td></tr><?php endforeach; ?></tbody></table></div></section><script>function categories(){const type=document.getElementById('jenis').value;const values=type==='masuk'?['infaq','usaha','iuran','donasi','lainnya']:['operasional','listrik_air','konsumsi','pendidikan','pemeliharaan','lainnya'];document.getElementById('kategori').replaceChildren(...values.map(x=>new Option(x.replaceAll('_',' '),x)));}if(document.getElementById('jenis'))categories();</script>
